import anndata 
import pandas as pd
from .preprocessing import get_sot_gene_matrix

# %% ../nbs/005_switch_search.ipynb 4
def build_gene_metrics_table(
    adata: "anndata.AnnData",
    group_column: str,
    condition_column: str = None,
    comparisons: list = None,
    group_vs_rest: bool = False,
    epsilon: float = 1e-6,
    n_jobs: int = -1
) -> pd.DataFrame:
    """
    Compare levels in `group_column` at gene level.
    If group_vs_rest=True, compares each group vs. all other cells.
    """
    adf = get_sot_gene_matrix(adata)
    if 'geneId' not in adf.var.columns:
        adf.var['geneId'] = adf.var.index

    def safe_sum_inner(X):
        if issparse(X):
            return np.asarray(X.sum(axis=0)).ravel()
        else:
            return np.asarray(X.sum(axis=0)).ravel()

    tasks = []
    groups = sorted(adf.obs[group_column].unique())
    if group_vs_rest:
        for g in groups:
            m1 = adf.obs[group_column] == g
            m2 = ~m1
            tasks.append((m1.values, m2.values, str(g), 'rest'))
    else:
        if condition_column is not None:
            prim, conds = sorted(adf.obs[group_column].unique()), sorted(adf.obs[condition_column].unique())
            for pg in prim:
                for c1, c2 in itertools.combinations(conds, 2):
                    m1 = (adf.obs[group_column] == pg) & (adf.obs[condition_column] == c1)
                    m2 = (adf.obs[group_column] == pg) & (adf.obs[condition_column] == c2)
                    tasks.append((m1.values, m2.values, f"{pg}:{c1}", f"{pg}:{c2}"))
        else:
            pairs = comparisons or itertools.combinations(groups, 2)
            for g1, g2 in pairs:
                m1 = adf.obs[group_column] == g1
                m2 = adf.obs[group_column] == g2
                tasks.append((m1.values, m2.values, str(g1), str(g2)))

    def proc(m1, m2, l1, l2):
        A1, A2 = adf[m1], adf[m2]
        X1, X2 = A1.X, A2.X
        n1, n2 = A1.n_obs, A2.n_obs
        c1, c2 = safe_sum_inner(X1), safe_sum_inner(X2)
        me1, me2 = c1/n1, c2/n2
        if issparse(X1):
            p1_raw = (X1 > 0).mean(axis=0)
            p2_raw = (X2 > 0).mean(axis=0)
            p1 = p1_raw.A1*100 if hasattr(p1_raw, "A1") else np.asarray(p1_raw).ravel()*100
            p2 = p2_raw.A1*100 if hasattr(p2_raw, "A1") else np.asarray(p2_raw).ravel()*100
        else:
            p1 = (X1 > 0).sum(axis=0).ravel()/n1*100
            p2 = (X2 > 0).sum(axis=0).ravel()/n2*100
        lfc = np.log((me1+epsilon)/(me2+epsilon))
        genes = adf.var.index.values
        tot = c1 + c2
        comp = f"{l1}__{l2}"
        return pd.DataFrame({
            'comparison': [comp]*len(genes),
            'gene_id': genes,
            'group_1': [l1]*len(genes),
            'group_2': [l2]*len(genes),
            'count_group1': c1,
            'count_group2': c2,
            'mean_expr_group1': me1,
            'mean_expr_group2': me2,
            'percent_expr_group1': p1,
            'percent_expr_group2': p2,
            'log_fc': lfc,
            'n_cells_group1': [n1]*len(genes),
            'n_cells_group2': [n2]*len(genes),
            'total_cells': [n1+n2]*len(genes),
            'total_count': tot
        })

    dfs = Parallel(n_jobs=n_jobs)(delayed(proc)(*t) for t in tasks)
    return pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()

