import matplotlib.pyplot as plt
import numpy as np

def plot_as_similarity(sim, cmap='magma'):
    """
    Enhanced AS‐similarity heatmap with colorbar and a 'magma' colormap.
    Text labels switch to white/black for better contrast.
    """
    fig, ax = plt.subplots(figsize=(8, 8))
    cax = ax.matshow(sim.values, cmap=cmap)
    # add colorbar with label
    cb = fig.colorbar(cax, ax=ax, fraction=0.046, pad=0.04)
    cb.set_label("Spearman ρ", rotation=270, labelpad=15)

    labels = sim.index.tolist()
    ax.set_xticks(np.arange(len(labels)))
    ax.set_yticks(np.arange(len(labels)))
    ax.set_xticklabels(labels, rotation=90, fontsize=10)
    ax.set_yticklabels(labels, fontsize=10)

    # annotate with correlation values and switch text color for visibility
    for (i, j), val in np.ndenumerate(sim.values):
        color = 'white' if val < 0.5 else 'black'
        ax.text(j, i, f"{val:.2f}", ha='center', va='center', color=color, fontsize=8)

    ax.set_title("AS Similarity (Spearman ρ)", pad=20)
    plt.tight_layout()
    plt.show()


# %% ../nbs/005_switch_search.ipynb 13
import numpy as np
import matplotlib.pyplot as plt
from scipy.cluster import hierarchy
from scipy.spatial.distance import squareform

def plot_as_similarity_ordered(sim, cmap='plasma'):
    """
    Reorders sim by 1–ρ linkage (loose ordering) and then plots a heatmap.
    """
    # 1) build a proper symmetric distance matrix = 1 – ρ
    D = 1 - sim.values
    D = (D + D.T) / 2      # enforce exact symmetry
    np.fill_diagonal(D, 0) # zero diagonal

    # 2) get condensed form
    condensed = squareform(D)

    # 3) linkage & leaf order
    Z = hierarchy.linkage(condensed, method='complete')
    order = hierarchy.dendrogram(Z, no_plot=True)['leaves']

    # 4) reorder your matrix & labels
    labels = sim.index.tolist()
    M = sim.values[np.ix_(order, order)]
    L = [labels[i] for i in order]

    # 5) plot
    fig, ax = plt.subplots(figsize=(8, 8))
    im = ax.matshow(M, cmap=cmap)
    cb = fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)
    cb.set_label("Spearman ρ", rotation=270, labelpad=15)

    ax.set_xticks(np.arange(len(L)))
    ax.set_yticks(np.arange(len(L)))
    ax.set_xticklabels(L, rotation=90, fontsize=10)
    ax.set_yticklabels(L, fontsize=10)

    # annotate
    for i in range(len(L)):
        for j in range(len(L)):
            v = M[i, j]
            c = 'white' if v < 0.5 else 'black'
            ax.text(j, i, f"{v:.2f}", ha='center', va='center', color=c, fontsize=8)

    ax.set_title("AS Similarity (Spearman ρ) — loosely ordered", pad=20)
    plt.tight_layout()
    plt.show()

